import math
ST={'j':False}
YT=-0.2
def control(obs):
    h=obs.get('hitch_deg',0.0) or 0.0
    rig=obs.get('rig') or {}
    tr=rig.get('trailer_rear') or [0.0,0.0]
    yr=tr[1]
    if abs(h)>60 or obs.get('status')=='JACKKNIFED': ST['j']=True
    if ST['j'] and abs(h)<45: ST['j']=False
    if ST['j']:
        return (0.0, 1.0)
    hdes=max(-25.0,min(25.0,-15.0*(yr-YT)))
    steer=max(-34.0,min(34.0,2.0*(h-hdes)))
    return (steer, -1.0)

