    h=obs.get('hitch_deg',0.0) or 0.0
    st=obs.get('status')
    tr=(obs.get('rig') or {}).get('trailer_rear') or [0.0,0.0]
    yr=tr[1]
    if S['ph']=='fwd':
        if S['t0'] is None:
            S['t0']=t
        if t-S['t0']<3.0:
            return (0.0, 0.4)
        S['ph']='rev'
        S['t0']=None
        return (0.0, 0.0)
    if st in ('PINNED','JACKKNIFED') or abs(h)>45:
        S['ph']='fwd'
        S['t0']=None
        return (0.0, 0.0)
    hdes=max(-12.0,min(4.0,-8.0-10.0*(yr+0.6)))
    steer=max(-34.0,min(34.0,2.0*(h-hdes)))
    return (steer, -0.25)

