ph = 'fwd'
odo = 0.0

def control(obs):
    global ph, odo
    dt = obs.get('dt', 0.1)
    m = obs.get('motion') or {}
    v = m.get('v_mps', 0.0)
    h = obs.get('hitch_deg', 0.0)
    rig = obs.get('rig') or {}
    tr = rig.get('trailer_rear') or [0.0, 0.0]
    y = tr[1]
    if ph == 'fwd':
        if v > 0.05:
            odo += v * dt
        if odo >= 2.5:
            ph = 'rev'
        else:
            return (14.0, 0.5, 180)
    e = y - 0.6
    steer = 1.5 * h + 4.0 * e
    steer = max(-30.0, min(30.0, steer))
    return (steer, -0.4, 180)

